const std=@import("std");const K=@import("experimental/soil_root_kernel_v2.zig");
fn perm(k:usize)[4]usize{var a=[_]usize{0,1,2,3};var out:[4]usize=undefined;var n:usize=4;var r=k;for(0..4)|i|{const j=r%n;r/=n;out[i]=a[j];for(j..n-1)|t|a[t]=a[t+1];n-=1;}return out;}
pub fn main()!void{
 var rng=std.Random.DefaultPrng.init(994135);const random=rng.random();const output=std.io.getStdOut().writer();var accepted:usize=0;var refused:usize=0;
 for(0..4000)|n|{const scale=std.math.pow(f64,2,@as(f64,@floatFromInt(n%501))-250);var s=K.State{.surface=scale*8,.soil=scale*4,.vapor=scale};var p=K.Params{.dt=1,.capacity=scale*8,.infiltration_rate=scale/2,.evaporation_rate=scale/8,.drainage_rate=scale/4,.conductance=1};for(0..4)|i|{s.cohorts[i]=.{.biomass=scale,.support=scale/2,.root_fraction=0.25,.storage_fraction=0.25,.water=scale/4};p.demand[i]=scale*@as(f64,@floatFromInt(1+random.uintLessThan(u32,8)))/16;p.exposure[i]=1;}
 if(n%2==1){s.soil=scale/64;p.infiltration_rate=0;p.evaporation_rate=0;p.drainage_rate=0;p.conductance=1024;}
 const original=s;const ref=K.step(s,p);try std.testing.expectEqualDeep(original,s);if(ref)|v|{accepted+=1;try output.writeAll("ROW ");try std.json.stringify(.{.before=s,.params=p,.result=v},.{},output);try output.writeByte('\n');}else refused+=1;
 for(0..24)|j|{const o=perm(j);var ps=s;var pp=p;for(0..4)|i|{ps.cohorts[i]=s.cohorts[o[i]];pp.demand[i]=p.demand[o[i]];pp.exposure[i]=p.exposure[o[i]];}const r=K.step(ps,pp);try std.testing.expect((r==null)==(ref==null));if(r)|v|{const base=ref.?;try std.testing.expectEqual(base.state.surface,v.state.surface);try std.testing.expectEqual(base.state.soil,v.state.soil);try std.testing.expectEqual(base.state.vapor,v.state.vapor);for(0..4)|i|{try std.testing.expectEqualDeep(base.state.cohorts[o[i]],v.state.cohorts[i]);try std.testing.expectEqual(base.root_receipts[o[i]],v.root_receipts[i]);try std.testing.expectEqual(base.store_receipts[o[i]],v.store_receipts[i]);try std.testing.expectEqual(base.h_paid[o[i]],v.h_paid[i]);}}}
 }
 var state=K.State{.soil=1,.vapor=1};state.cohorts[0]=.{.biomass=1,.support=0.5,.root_fraction=0.5,.storage_fraction=0.5,.water=1};const params=K.Params{.dt=1,.capacity=1,.conductance=1,.demand=.{0.5,0,0,0},.exposure=.{1,0,0,0}};
 const both=K.step(state,params).?;try std.testing.expectEqual(@as(f64,0.25),both.root_receipts[0]);try std.testing.expectEqual(@as(f64,0.25),both.store_receipts[0]);try std.testing.expectEqual(@as(f64,1),both.h_paid[0]);var zero=params;zero.demand=.{0,0,0,0};try std.testing.expectEqualDeep(state,K.step(state,zero).?.state);
 for([_]f64{-1,std.math.nan(f64),std.math.inf(f64)})|bad|{var p=params;p.capacity=bad;try std.testing.expect(K.step(state,p)==null);p=params;p.dt=bad;try std.testing.expect(K.step(state,p)==null);p=params;p.demand[0]=bad;try std.testing.expect(K.step(state,p)==null);var s=state;s.cohorts[0].water=bad;try std.testing.expect(K.step(s,params)==null);}
 var tiny=K.State{.surface=0x1p-200,.vapor=1};var tp=K.Params{.dt=1,.capacity=1,.infiltration_rate=0x1p-200,.evaporation_rate=0x1p-200};try std.testing.expect(K.step(tiny,tp)!=null);tiny.vapor=0;tp.capacity=-1;try std.testing.expect(K.step(tiny,tp)==null);
 std.debug.print("4000 cases x24 permutations accepted={d}, refused={d}; invalid/zero/root+storage/tinyreceiver gates pass\n",.{accepted,refused});try std.testing.expect(accepted>0);
}
